def _create_grammar(self, request: "Request") -> StructuredOutputGrammar:
    struct_request = request.structured_output_request
    assert struct_request is not None
    # Note that the request was validated in the engine core client,
    # so at this point we know it is a supported type of request. Grammar
    # compilation may still fail; the Future carries that error to the
    # scheduler so it can fail only this request.
    try:
        request_type, grammar_spec = struct_request.structured_output_key
        assert self.backend is not None
        return self.backend.compile_grammar(request_type, grammar_spec)
    except Exception:
        logger.exception(
            "Failed to compile grammar for request %s", request.request_id
        )
        raise

@dataclasses.dataclass
class StructuredOutputRequest:
    params: StructuredOutputsParams
    _grammar: (
        Future[StructuredOutputGrammar] | StructuredOutputGrammar | Exception | None
    ) = None
    reasoning_ended: bool | None = None
    # Absolute index into the request's all_token_ids of the last reasoning
    # token (the reasoning-end marker). Tokens at or before this index are
    # reasoning content and must never be fed to the grammar. Only set when
    # reasoning ends in a step whose tokens the scheduler advances immediately
    # (structural tags + speculative decoding, see #42452).
    reasoning_end_token_index: int | None = None
    reasoning_parser_kwargs: dict[str, Any] | None = None
    # Cached per request; do not share reasoning parsers across requests because
    # their behavior can depend on reasoning_parser_kwargs.
    reasoner: "ReasoningParser | None" = None

    @staticmethod
    def from_sampling_params(
        sampling_params: SamplingParams | None,
    ) -> "StructuredOutputRequest | None":
        if sampling_params is None:
            return None
        params = sampling_params.structured_outputs
        if not params or params.all_constraints_none():
            return None
        return StructuredOutputRequest(params=params)

def _check_grammar_completion(self) -> bool:
    if isinstance(self._grammar, Future):
        try:
            # We will check whether the future is ready within 100 us
            self._grammar = self._grammar.result(timeout=0.0001)
        except TimeoutError:
            return False
        except Exception as e:
            self._grammar = e
    return True

@property
def is_grammar_ready(self) -> bool:
    return self._check_grammar_completion()

@property
def grammar(self) -> StructuredOutputGrammar | Exception | None:
    if not self._check_grammar_completion():
        return None
    return cast(StructuredOutputGrammar | Exception | None, self._grammar)

@grammar.setter
def grammar(
    self, grammar: StructuredOutputGrammar | Future[StructuredOutputGrammar]
) -> None:
    self._grammar = grammar

@functools.cached_property
def structured_output_key(self) -> StructuredOutputKey:
    return get_structured_output_key(self.params)

def get_structured_output_key(params: StructuredOutputsParams) -> StructuredOutputKey:
    if params.json is not None:
        if not isinstance(params.json, str):
            json_str = json.dumps(params.json)
        else:
            json_str = params.json
        return StructuredOutputOptions.JSON, json_str
    if params.json_object:
        return StructuredOutputOptions.JSON_OBJECT, ""
    if params.regex is not None:
        return StructuredOutputOptions.REGEX, params.regex
    if params.choice is not None:
        if not isinstance(params.choice, str):
            json_str = json.dumps(params.choice)
        else:
            json_str = params.choice
        return StructuredOutputOptions.CHOICE, json_str
    if params.grammar is not None:
        return StructuredOutputOptions.GRAMMAR, params.grammar
    if params.structural_tag is not None:
        return StructuredOutputOptions.STRUCTURAL_TAG, params.structural_tag
    raise ValueError("No valid structured output parameter found")

def compile_grammar(
    self, request_type: StructuredOutputOptions, grammar_spec: str
) -> StructuredOutputGrammar:
    if request_type == StructuredOutputOptions.JSON:
        ctx = self.compiler.compile_json_schema(
            grammar_spec, any_whitespace=not self.disable_any_whitespace
        )
    elif request_type == StructuredOutputOptions.JSON_OBJECT:
        ctx = self.compiler.compile_json_schema(
            '{"type": "object"}', any_whitespace=not self.disable_any_whitespace
        )
    elif request_type == StructuredOutputOptions.GRAMMAR:
        ctx = self.compiler.compile_grammar(grammar_spec)
    elif request_type == StructuredOutputOptions.REGEX:
        ctx = compile_regex_with_timeout(
            self.compiler.compile_regex,
            grammar_spec,
        )
    elif request_type == StructuredOutputOptions.STRUCTURAL_TAG:
        s_tag = json.loads(grammar_spec)
        if "structures" in s_tag:
            # Falling back to deprecated method of compiling structural tag
            tags = [
                xgr.StructuralTagItem(
                    begin=s["begin"],
                    schema=json.dumps(s["schema"]),
                    end=s["end"],
                )
                for s in s_tag["structures"]
            ]
            ctx = self.compiler.compile_structural_tag(tags, s_tag["triggers"])
        else:
            ctx = self.compiler.compile_structural_tag(grammar_spec)
    else:
        logger.error(
            "Validation should have already occurred. Please file an issue."
        )
        raise ValueError(
            f"grammar is not of valid supported types. ({request_type!s})"
        )

    return XgrammarGrammar(
        matcher=xgr.GrammarMatcher(
            ctx,
            max_rollback_tokens=self.num_speculative_tokens,
        ),
        vocab_size=self.vocab_size,
        ctx=ctx,
    )

def validate_xgrammar_grammar(sampling_params: SamplingParams) -> None:
    """Validate that the request is supported by structured output.

    Raises ValueError if the request is not supported.
    """
    if sampling_params.structured_outputs is None:
        return

    so_params = sampling_params.structured_outputs

    if so_params.regex:
        try:
            compile_regex_with_timeout(
                xgr.Grammar.from_regex,
                so_params.regex,
            )
        except Exception as err:
            raise ValueError(
                f"Failed to transform regex into a grammar: {err}"
            ) from err

    if so_params.choice:
        choice_grammar = choice_as_grammar(so_params.choice)
        try:
            xgr.Grammar.from_ebnf(choice_grammar)
        except Exception as err:
            raise ValueError(
                f"Failed to transform choices into a grammar: {err}"
            ) from err
        so_params.choice = None
        so_params.grammar = choice_grammar
        return

def choice_as_grammar(choice: list[str]) -> str:
    def escape_ebnf_string(s: str) -> str:
        """Escape special characters in a EBNF string."""
        # Escape double quotes and backslashes
        return re.sub(r'(["\\])', r"\\\1", s)

    escaped_choices = (escape_ebnf_string(c) for c in choice)
    grammar = "root ::= " + " | ".join(f'"{c}"' for c in escaped_choices)
    return grammar

@staticmethod
def _is_blocked_waiting_status(status: RequestStatus) -> bool:
    return status in (
        RequestStatus.WAITING_FOR_STRUCTURED_OUTPUT_GRAMMAR,
        RequestStatus.WAITING_FOR_REMOTE_KVS,
        RequestStatus.WAITING_FOR_STREAMING_REQ,
    )

def _enqueue_waiting_request(self, request: Request) -> None:
    if self._is_blocked_waiting_status(request.status):
        self.skipped_waiting.add_request(request)
    else:
        self.waiting.add_request(request)

# try to promote blocked statuses while traversing skipped queue.
if self._is_blocked_waiting_status(
    request.status
) and not self._try_promote_blocked_waiting_request(request):
    if request.status == RequestStatus.WAITING_FOR_REMOTE_KVS:
        logger.debug(
            "%s is still in WAITING_FOR_REMOTE_KVS state.",
            request_id,
        )
    request_queue.pop_request()
    step_skipped_waiting.prepend_request(request)

def _try_promote_blocked_waiting_request(self, request: Request) -> bool:
    """
    Try to promote a blocked waiting request back to schedulable states.
    """
    if request.status == RequestStatus.WAITING_FOR_REMOTE_KVS:
        # finished_recving_kv_req_ids is populated during
        # update_from_output(), based on worker-side connector signals
        # in KVConnectorOutput.finished_recving
        if request.request_id not in self.finished_recving_kv_req_ids:
            return False
        self._update_waiting_for_remote_kv(request)
        if request.num_preemptions:
            request.status = RequestStatus.PREEMPTED
        else:
            request.status = RequestStatus.WAITING
        return True

    if request.status == RequestStatus.WAITING_FOR_STRUCTURED_OUTPUT_GRAMMAR:
        structured_output_req = request.structured_output_request
        if not structured_output_req or structured_output_req.grammar is None:
            return False
        if isinstance(structured_output_req.grammar, Exception):
            self.grammar_compile_error_reqs.add(request.request_id)
            return False
        request.status = RequestStatus.WAITING
        return True

error_req_ids = set(self.grammar_compile_error_reqs)
self.grammar_compile_error_reqs.clear()
if failed_kv_load_req_ids and not self.recompute_kv_load_failures:
    error_req_ids.update(failed_kv_load_req_ids)

if error_req_ids:
    error_reqs = self.finish_requests(
        error_req_ids, RequestStatus.FINISHED_ERROR
    )
    for request in error_reqs:
        outputs[request.client_index].append(
            EngineCoreOutput(
                request_id=request.request_id,
                new_token_ids=[],
                finish_reason=request.get_finished_reason(),
                events=request.take_events(),
                trace_headers=request.trace_headers,
            )
        )

def get_grammar_bitmask(
    self, scheduler_output: SchedulerOutput
) -> GrammarOutput | None:
    # Collect list of scheduled request ids that use structured output.
    # The corresponding rows of the bitmask will be in this order.
    if not scheduler_output.has_structured_output_requests:
        return None

    structured_output_request_ids = [
        req_id
        for req_id in scheduler_output.num_scheduled_tokens
        if (req := self.requests.get(req_id))
        and (req.use_structured_output and not req.is_prefill_chunk)
    ]
    if not structured_output_request_ids:
        return None

    bitmask = self.structured_output_manager.grammar_bitmask(
        self.requests,
        structured_output_request_ids,
        scheduler_output.scheduled_spec_decode_tokens,
    )
    return GrammarOutput(structured_output_request_ids, bitmask)

@dataclass
class OutlinesBackend(StructuredOutputBackend):
    def __post_init__(self):
        self.vocabulary = get_outlines_vocabulary(self.tokenizer)
        self.cache = get_outlines_cache()

    def _compile_index(
        self, regex_string: str, vocabulary: OutlinesVocabulary
    ) -> oc.Index:
        cache_key = f"{vocabulary._hash}_{regex_string}"
        if cache_key in self.cache:
            return self.cache[cache_key]

        index = compile_regex_with_timeout(
            lambda pat: oc.Index(pat, vocabulary.inner),
            regex_string,
        )
        self.cache[cache_key] = index

        return index

    def compile_grammar(
        self, request_type: StructuredOutputOptions, grammar_spec: str
    ) -> StructuredOutputGrammar:
        if request_type == StructuredOutputOptions.JSON:
            regex = json_schema.build_regex_from_schema(grammar_spec)
        elif request_type == StructuredOutputOptions.REGEX:
            regex = grammar_spec
        elif request_type == StructuredOutputOptions.CHOICE:
            choices = ast.literal_eval(grammar_spec)
            choices = [regex_escape(c) for c in choices]
            regex = "(" + "|".join(choices) + ")"
        else:
            raise ValueError(
                f"Invalid request type for Outlines backend ({request_type!s})"
            )
        index = self._compile_index(regex, self.vocabulary)
        max_rollback_tokens = (
            self.vllm_config.speculative_config.num_speculative_tokens
            if self.vllm_config.speculative_config is not None
            else 0
        )
        return OutlinesGrammar(
            vocab_size=self.vocab_size,
            guide=oc.Guide(index, max_rollback=max_rollback_tokens),
        )

max_rollback_tokens = (
    self.vllm_config.speculative_config.num_speculative_tokens
    if self.vllm_config.speculative_config is not None
    else 0
)

if max_rollback_tokens > 0:
    raise ValueError(
        "LM Format Enforcer backend does not support speculative tokens"
    )

token_enforcer = lmformatenforcer.TokenEnforcer(
    tokenizer_data=self.tokenizer_data,
    parser=character_level_parser,
)
return LMFormatEnforcerGrammar(token_enforcer)
